#include <iostream>
namespace mylib {
    void display() {
        std::cout << "Hello from mylib!" << std::endl;
    }
}
int main() {
    mylib::display(); // Using scope resolution to access 'display' in 'mylib'
    using namespace mylib;
    display(); // Calling 'display' after 'using' directive
    return 0;
}
